def solution(operations):
    stack = []
    min_stack = []
    res = []
    for op in operations:
        cmd = op[0]
        if cmd == 'push':
            val = op[1]
            stack.append(val)
            if not min_stack or val <= min_stack[-1]:
                min_stack.append(val)
        elif cmd == 'pop':
            if stack:
                val = stack.pop()
                if val == min_stack[-1]:
                    min_stack.pop()
        elif cmd == 'getMin':
            res.append(min_stack[-1] if min_stack else None)
    return res
